func (s *scriptRunner) run(comm Communicator, scripts []io.ReadCloser) error {
	// The provisioner node may hang around a bit longer before it's cleaned up
	// in the graph, but we can disconnect the communicator after we run the
	// commands. We do still want to drop the connection if we're canceled early
	// for some reason, so build a new context from the original.
	cmdCtx, cancel := context.WithCancel(s.ctx)
	defer cancel()

	retryCtx, cancel := context.WithTimeout(cmdCtx, comm.Timeout())
	defer cancel()

	// Wait and retry until we establish the connection
	err := Retry(retryCtx, func() error {
		return comm.Connect(s.out)
	})
	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-cmdCtx.Done()
		comm.Disconnect()
	}()

